// Ignore delivery statuses; emit one item per inbound message.
const body = $('WhatsApp webhook').first().json.body;
const out = [];
for (const e of body.entry ?? []) for (const ch of e.changes ?? []) for (const m of ch.value?.messages ?? [])
  out.push({ json: { id: m.id, from: m.from, text: m.text?.body ?? m.button?.text ?? m.interactive?.button_reply?.title ?? '',
    buttonId: m.interactive?.button_reply?.id ?? m.button?.payload ?? null, referral: m.referral ?? null } });
return out;

// The qualification state machine. State lives on the HubSpot contact (fib_qual_step),
// so this node only decides: which properties to save and what to send next.
const cfg = $('Config').first().json;
const m = $('Extract messages').item.json;
const c = $json.results?.[0];
const p = c?.properties ?? {};
const now = new Date().toISOString();
const btn = m.buttonId;
const text = (m.text ?? '').trim();
const low = ' ' + text.toLowerCase().replace(/[^\p{L}\p{M}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ') + ' ';
const any = (ws) => ws.some(w => low.includes(' ' + w + ' '));
const budgets = [{ id: 'budget_lt25', title: 'Under ₹25L', lakh: 15 }, { id: 'budget_25_40', title: '₹25–40L', lakh: 30 }, { id: 'budget_40p', title: '₹40L+', lakh: 45 }];
const times = [{ id: 'time_0_3', title: '0–3 months', months: 3 }, { id: 'time_3_6', title: '3–6 months', months: 6 }, { id: 'time_later', title: 'Later', months: 12 }];
const buttons = (body, opts) => ({ type: 'interactive', interactive: { type: 'button', body: { text: body },
  action: { buttons: opts.map(o => ({ type: 'reply', reply: { id: o.id, title: o.title } })) } } });
const say = (body) => ({ type: 'text', text: { body } });
const r = (action, props, message) => ({ json: { action, contactId: c?.id, phone: m.from, props: { fib_last_inbound_at: now, fib_last_wa_message_id: m.id, ...props }, message, contact: { ...p, ...props } } });

if (!c) return r('unknown_sender', {}, null); // exercise N4: create the contact (Click-to-WhatsApp)
if (p.fib_last_wa_message_id === m.id) return r('duplicate', {}, null);
if (any(['stop', 'unsubscribe', 'band karo', 'message mat karo']) && text.split(/\s+/).length <= 3)
  return r('send', { fib_wa_opt_out: 'true', fib_qual_step: 'opted_out' }, say(`You won't get any more messages from ${cfg.brand}. Reply START if you change your mind.`));
if (p.fib_wa_opt_out === 'true') return r('ignore', {}, null);
if (any(['call me', 'talk to a person', 'human', 'call karo', 'baat karni hai', 'speak to']))
  return r('handoff', { fib_lead_score: p.fib_lead_score || 'unscored' }, null);

const step = p.fib_qual_step;
if (step === 'awaiting_optin_reply' || step === 'new') {
  if (btn === 'welcome_no' || /^(no|not now|nahi)/i.test(text)) return r('send', { fib_qual_step: 'declined', hs_lead_status: 'BAD_TIMING' }, say('No problem. Message us here any time.'));
  return r('send', { fib_qual_step: 'awaiting_budget', fib_last_outbound_at: now }, buttons('Great! What budget are you planning for the investment?', budgets));
}
if (step === 'awaiting_budget') {
  const b = budgets.find(o => o.id === btn);
  if (!b) return r('send', {}, buttons('Sorry, please pick one of the options below.', budgets)); // exercise N3: re-ask once, then hand off
  if (b.lakh < cfg.minBudgetLakh) return r('send', { fib_budget_lakh: String(b.lakh), fib_qual_step: 'unqualified', hs_lead_status: 'UNQUALIFIED', fib_lead_score: 'unqualified' },
    say(`Thank you for sharing. A ${cfg.brand} outlet needs a larger budget, so it may not be the right fit today.`));
  return r('send', { fib_budget_lakh: String(b.lakh), fib_qual_step: 'awaiting_timeline', fib_last_outbound_at: now }, buttons('When would you like to open your outlet?', times));
}
if (step === 'awaiting_timeline') {
  const t = times.find(o => o.id === btn);
  if (!t) return r('send', {}, buttons('Sorry, please pick one of the options below.', times));
  const budget = Number(p.fib_budget_lakh);
  const score = budget < cfg.minBudgetLakh ? 'unqualified' : t.months <= 3 ? 'hot' : t.months <= 6 ? 'warm' : 'cold';
  return r('handoff', { fib_timeline_months: String(t.months), fib_lead_score: score }, null);
}
return r('log', {}, null); // a consultant owns the chat now

// City match first, then fewest open leads. Same rule as src/rules.mjs pickConsultant().
const cfg = $('Config').first().json;
const lead = $('Decide next step').item.json;
const owners = $('HubSpot: owners').first().json.results;
const open = $('HubSpot: open leads').first().json.results;
const idByEmail = Object.fromEntries(owners.map(o => [o.email, o.id]));
const count = (email) => open.filter(x => x.properties.hubspot_owner_id === idByEmail[email]).length;
const city = (lead.contact.city || '').toLowerCase();
const free = cfg.consultants.filter(k => k.available);
const local = free.filter(k => k.cities.includes(city));
const pick = [...(local.length ? local : free)].sort((a, b) => count(a.email) - count(b.email))[0];
const score = lead.contact.fib_lead_score || 'unscored';
const dueMin = { hot: 15, warm: 120, cold: 1440 }[score] ?? 60;
const summary = `City: ${lead.contact.city || '—'} · Budget: ₹${lead.contact.fib_budget_lakh || '?'}L · Timeline: ${lead.contact.fib_timeline_months || '?'} months · Score: ${score}`;
return [{ json: { ...lead, consultant: pick, ownerId: idByEmail[pick.email], score, summary,
  due: new Date(Date.now() + dueMin * 60000).toISOString() } }];
